// The Family Tree copy (family-rollups-and-tree NFR-13, FR-26, FR-44; QA-26,
// QA-44, QA-85). The default sentences the PRD and the design spec fix are
// asserted as literals (the one content test); everything else is a RULE swept
// over a corpus generated by calling every count-bearing builder at counts of
// zero, one and many (ui.md v1.0.5, testing.md v1.0.22), so a new builder joins
// the sweep by being added to the module and to the list below.

import { describe, it, expect } from 'vitest'
import { readFileSync, readdirSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import * as copy from './familyTreeCopy'

const COUNTS = [0, 1, 2, 1204]
const KINDS = copy.KIND_KEYS

/** Every count-bearing string the module can build. */
function corpus(): string[] {
  const out: string[] = []
  for (const n of COUNTS) {
    out.push(copy.headlineSentence(n, n, n), copy.ofWorld(n), copy.genusSpecies(n), copy.notPlacedSub(n),
      copy.notPlacedReason(Math.max(1, n)), copy.notPlacedRowLabel(n), copy.notPlacedLine(n), copy.showInTable(n),
      copy.notSingleSpeciesLine(n))
    const of = copy.orderFigures(n, n + 3, n, n + 1)
    out.push(of.seen + of.rest1 + of.families + of.rest2)
    const sw = copy.seenOfWorld(n, n + 9)
    out.push(sw.seen + sw.rest)
    for (const k of KINDS) out.push(copy.itemsLabel(k, n))
    out.push(copy.familyRowLabel('Ducks', n, n + 2, [n, n, n], [n, n, n]))
  }
  return out
}

/** The plural nouns this copy can put after a count. */
const PLURAL_NOUN = /(^|[^0-9,.])1 (?:other )?(families|orders|entries|photos|recordings|videos)\b/
/** A plural verb or pronoun in a sentence whose subject is counted at one. */
const PLURAL_AGREEMENT = /(^|[^0-9,.])1 (?:other )?(?:species|entry|entries)\b[^.]*\b(are|have|they|them)\b/

describe('the content (the PRD\'s and the design spec\'s sentences, verbatim)', () => {
  it('the phase and state sentences', () => {
    expect(copy.SETUP_BODY).toBe("The Family Tree tab loads automatically from your stored eBird backup. You haven't saved one yet.")
    expect(copy.FAMILY_DATA_ERROR).toBe("SnowRaven couldn't load its bird family data.")
    expect(copy.EMPTY_UNFILTERED).toBe('No countable species in your eBird backup yet.')
    expect(copy.EMPTY_FILTERED).toBe('No species match these filters.')
    expect(copy.FILTER_NOTE).toBe('Family totals are world species and do not change with the filters.')
    expect(copy.ESCAPEE_STATUS).toBe('Escapee status comes from the escapee check on Statistics, which has not finished for this export, so species it has not settled are counted.')
    expect(copy.ML_NONE_SENTENCE).toBe('Photo, audio, and video figures need your Macaulay Library export, saved in Settings under Default Files.')
  })
  it('the count-bearing lines at one and at many (FR-26, FR-59)', () => {
    expect(copy.notSingleSpeciesLine(1)).toBe('1 other entry in your backup is not a single species, so it has no place on the tree.')
    expect(copy.notSingleSpeciesLine(3)).toBe('3 other entries in your backup are not a single species, so they have no place on the tree.')
    expect(copy.notPlacedLine(1)).toBe('1 species is not placed on the tree.')
    expect(copy.notPlacedLine(1204)).toBe('1,204 species are not placed on the tree.')
    expect(copy.headlineSentence(1, 1, 1)).toBe('1 species in 1 family and 1 order.')
  })
  it('the media scoping note takes only the clause that applies', () => {
    const join = (p: ReturnType<typeof copy.mediaScopeParts>) => p === null ? null : p.before + (p.region ?? '') + p.middle + (p.year ?? '') + p.after
    expect(join(copy.mediaScopeParts(null, null))).toBeNull()
    expect(join(copy.mediaScopeParts('Marin, CA', '2021'))).toBe('Photo, audio, and video figures count only media from Marin, CA dated 2021.')
    expect(join(copy.mediaScopeParts('Marin, CA', null))).toBe('Photo, audio, and video figures count only media from Marin, CA.')
    expect(join(copy.mediaScopeParts(null, '2021'))).toBe('Photo, audio, and video figures count only media dated 2021.')
  })
})

describe('the rules over the generated corpus (QA-85)', () => {
  const all = corpus()
  it('the corpus is not empty and reaches every builder at one', () => {
    expect(all.length).toBeGreaterThanOrEqual(60)
  })
  it('no count of one takes a plural noun, verb or pronoun', () => {
    let atOne = 0
    for (const s of all) {
      for (const sentence of s.split(/(?<=\.)\s/)) {
        if (/(^|[^0-9,.])1 /.test(sentence)) atOne += 1
        expect(PLURAL_NOUN.test(sentence), `"${sentence}" pairs 1 with a plural noun`).toBe(false)
        expect(PLURAL_AGREEMENT.test(sentence), `"${sentence}" pairs a subject of 1 with a plural verb or pronoun`).toBe(false)
      }
    }
    expect(atOne).toBeGreaterThan(10)
    expect(copy.showInTable(1)).toBe('Show it in the table')
    expect(copy.showInTable(2)).toBe('Show them in the table')
  })
  it('the rules can fail: each rejects the wrong form it names', () => {
    expect(PLURAL_NOUN.test('1 families')).toBe(true)
    expect(PLURAL_AGREEMENT.test('1 species are not placed on the tree.')).toBe(true)
    expect(PLURAL_AGREEMENT.test('1 other entry in your backup is not a single species, so they have no place.')).toBe(true)
  })
  it('a nonzero share never reads as a bare 0%', () => {
    expect(copy.share(1, 400)).toBe('<1%')
    expect(copy.share(0, 400)).toBe('0%')
  })
  it('counts take locale grouping', () => {
    expect(copy.formatCount(1204)).toBe('1,204')
    expect(copy.genusSpecies(1204)).toBe('1,204 species')
  })
})

describe('no em dash anywhere the tab renders (NFR-13)', () => {
  const dir = fileURLToPath(new URL('.', import.meta.url))
  const comps = fileURLToPath(new URL('../components/familyTree/', import.meta.url))
  const files = [
    ...readdirSync(dir).filter(f => /^familyTree[A-Za-z]*\.ts$/.test(f) && !f.endsWith('.test.ts')).map(f => dir + f),
    ...readdirSync(comps).filter(f => f.endsWith('.tsx') && !f.endsWith('.test.tsx')).map(f => comps + f),
  ]
  it('in the copy module, the components and the tab\'s Help section', () => {
    expect(files.length).toBeGreaterThan(5)
    const dash = String.fromCharCode(0x2014)
    for (const f of files) expect(readFileSync(f, 'utf8').includes(dash), f).toBe(false)
    const help = readFileSync(fileURLToPath(new URL('../../../docs/HELP.md', import.meta.url)), 'utf8')
    const i = help.indexOf('\n## Family Tree\n')
    expect(i).toBeGreaterThan(-1)
    expect(help.slice(i, help.indexOf('\n## ', i + 5)).includes(dash)).toBe(false)
  })
  it('no count-bearing string is built inside a component (the source holds no plural ternary)', () => {
    for (const f of files.filter(f => f.endsWith('.tsx'))) {
      const code = readFileSync(f, 'utf8').split('\n').filter(l => !l.trimStart().startsWith('//')).join('\n')
      expect(/=== 1 \?/.test(code), f).toBe(false)
      expect(/toLocaleString\(/.test(code), f).toBe(false)
    }
  })
})
